'use server'

import { revalidatePath } from 'next/cache'

export async function toggleNotificationPreference(userId: string, currentPreference: boolean): Promise<void> {
  // In a real app, update the database here
  // await db.user.update({ where: { id: userId }, data: { notificationsEnabled: !currentPreference } })

  // Revalidate the current page to reflect the updated preference
  revalidatePath('/', 'page')
}

'use client'

import { useState } from 'react'
import { toggleNotificationPreference } from '@/app/actions/notifications'

interface NotificationToggleProps {
  userId: string
  initialEnabled: boolean
}

export function NotificationToggle({ userId, initialEnabled }: NotificationToggleProps) {
  const [isEnabled, setIsEnabled] = useState(initialEnabled)
  const [isPending, setIsPending] = useState(false)

  const handleToggle = async () => {
    setIsPending(true)
    await toggleNotificationPreference(userId, isEnabled)
    setIsEnabled(!isEnabled)
    setIsPending(false)
  }

  return (
    <button
      onClick={handleToggle}
      disabled={isPending}
      className={`px-4 py-2 rounded ${isEnabled ? 'bg-green-500' : 'bg-gray-500'} text-white`}
    >
      {isPending ? 'Updating...' : isEnabled ? 'Notifications: ON' : 'Notifications: OFF'}
    </button>
  )
}
